// Panels scroll by dragging the paper itself, like sliding a sheet on a desk: no browser scrollbar.
// Touch keeps native momentum scrolling; mouse and pen drag after a small threshold so clicks still land.
const style=document.createElement('style');style.textContent=`.drag-scroll{scrollbar-width:none;overscroll-behavior:contain;cursor:grab}.drag-scroll::-webkit-scrollbar{display:none}.drag-scroll.is-dragging{cursor:grabbing;user-select:none}.drag-scroll.is-dragging *{cursor:grabbing!important}
.drag-scroll[data-scroll-y~=up]{--fade-top:28px}.drag-scroll[data-scroll-y~=down]{--fade-bottom:28px}.drag-scroll[data-scroll-x~=left]{--fade-left:28px}.drag-scroll[data-scroll-x~=right]{--fade-right:28px}
.drag-scroll[data-scroll-y]{-webkit-mask-image:linear-gradient(to bottom,transparent,#000 var(--fade-top,0),#000 calc(100% - var(--fade-bottom,0px)),transparent);mask-image:linear-gradient(to bottom,transparent,#000 var(--fade-top,0),#000 calc(100% - var(--fade-bottom,0px)),transparent)}
.drag-scroll-thumb{position:fixed;z-index:2147483000;width:3px;border-radius:2px;background:var(--app-ink,#4c4330);opacity:.35;pointer-events:none;transition:opacity .25s}.drag-scroll-thumb[hidden]{display:block;opacity:0}
.drag-scroll[data-scroll-x]{-webkit-mask-image:linear-gradient(to right,transparent,#000 var(--fade-left,0),#000 calc(100% - var(--fade-right,0px)),transparent);mask-image:linear-gradient(to right,transparent,#000 var(--fade-left,0),#000 calc(100% - var(--fade-right,0px)),transparent)}`;
document.head.append(style);
const typing=t=>t.closest?.('input,textarea,select,[contenteditable=""],[contenteditable=true],summary');
// snap: a row selector; after a drag the list settles with a row edge at the top.
export function dragScroll(el,{axis='y',ignore='',fade=true,snap=''}={}){
 if(!el||el.dataset.dragScroll)return ()=>{};el.dataset.dragScroll=axis;el.classList.add('drag-scroll');
 let press=null,suppress=false,hideThumb=0;
 // A thin position marker appears only while the list is moving; wheel and keyboard scrolling show it too.
 const thumb=document.createElement('div');thumb.className='drag-scroll-thumb';thumb.hidden=true;thumb.setAttribute('aria-hidden','true');document.body.append(thumb);
 const showThumb=()=>{if(axis!=='y'||el.scrollHeight<=el.clientHeight+2||!el.isConnected||!el.offsetParent){thumb.hidden=true;return;}const r=el.getBoundingClientRect(),h=Math.max(24,r.height*el.clientHeight/el.scrollHeight),top=r.top+(r.height-h)*el.scrollTop/(el.scrollHeight-el.clientHeight);Object.assign(thumb.style,{left:r.right-6+'px',top:top+'px',height:h+'px'});thumb.hidden=false;clearTimeout(hideThumb);hideThumb=setTimeout(()=>{thumb.hidden=true;},650);};
 const settle=()=>{if(!snap||axis!=='y')return;const rows=[...el.querySelectorAll(snap)];if(!rows.length)return;const base=el.getBoundingClientRect().top-el.scrollTop;let best=el.scrollTop,gap=Infinity;for(const row of rows){const y=row.getBoundingClientRect().top-base;if(Math.abs(y-el.scrollTop)<gap){gap=Math.abs(y-el.scrollTop);best=y;}}if(el.scrollTop+el.clientHeight>=el.scrollHeight-2)return;el.scrollTo({top:best,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});};
 const fades=()=>{if(!fade)return;if(axis==='y'){const top=el.scrollTop>2,bottom=el.scrollTop+el.clientHeight<el.scrollHeight-2;if(top||bottom)el.dataset.scrollY=[top&&'up',bottom&&'down'].filter(Boolean).join(' ');else delete el.dataset.scrollY;}else{const left=el.scrollLeft>2,right=el.scrollLeft+el.clientWidth<el.scrollWidth-2;if(left||right)el.dataset.scrollX=[left&&'left',right&&'right'].filter(Boolean).join(' ');else delete el.dataset.scrollX;}};
 const down=e=>{if(e.pointerType==='touch'||e.button!==0||typing(e.target)||ignore&&e.target.closest?.(ignore))return;press={id:e.pointerId,x:e.clientX,y:e.clientY,left:el.scrollLeft,top:el.scrollTop,moved:false,velocity:0,t:e.timeStamp,last:axis==='y'?e.clientY:e.clientX};};
 const move=e=>{if(!press||press.id!==e.pointerId)return;const dx=e.clientX-press.x,dy=e.clientY-press.y,d=axis==='y'?dy:dx;if(!press.moved){if(Math.abs(d)<6)return;press.moved=true;el.setPointerCapture(e.pointerId);el.classList.add('is-dragging');}e.preventDefault();if(axis==='y')el.scrollTop=press.top-dy;else el.scrollLeft=press.left-dx;const p=axis==='y'?e.clientY:e.clientX,dt=Math.max(1,e.timeStamp-press.t);press.velocity=(p-press.last)/dt;press.last=p;press.t=e.timeStamp;};
 const up=e=>{if(!press||press.id!==e.pointerId)return;const p=press;press=null;if(!p.moved)return;suppress=true;el.classList.remove('is-dragging');if(el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId);
  // A short glide after release keeps the drag feeling physical.
  let v=-p.velocity*16;const glide=()=>{if(press)return;if(Math.abs(v)<.4){settle();return;}if(axis==='y')el.scrollTop+=v;else el.scrollLeft+=v;v*=.92;requestAnimationFrame(glide);};if(!matchMedia('(prefers-reduced-motion: reduce)').matches)requestAnimationFrame(glide);else settle();};
 const click=e=>{if(suppress){suppress=false;e.preventDefault();e.stopPropagation();}};
 el.addEventListener('pointerdown',down);el.addEventListener('pointermove',move,{passive:false});el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);el.addEventListener('click',click,true);el.addEventListener('scroll',fades,{passive:true});el.addEventListener('scroll',showThumb,{passive:true});
 const resize=typeof ResizeObserver==='undefined'?null:new ResizeObserver(fades);resize?.observe(el);const mutation=new MutationObserver(fades);mutation.observe(el,{childList:true,subtree:true});fades();
 return ()=>{el.removeEventListener('pointerdown',down);el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',up);el.removeEventListener('pointercancel',up);el.removeEventListener('click',click,true);el.removeEventListener('scroll',fades);el.removeEventListener('scroll',showThumb);thumb.remove();resize?.disconnect();mutation.disconnect();el.classList.remove('drag-scroll');delete el.dataset.dragScroll;};
}
